// ============================================================
// CLASSIFY HUBSPOT EVENTS BY DESTINATION
// ============================================================
// Each event has a propertyName. We check it against
// known route maps and tag it with a destination.
//
// Note on canon_engagement_status routing:
// HubSpot Starter doesn't support hs_email_last_open_date
// as a webhook trigger. Instead we subscribe to our own
// canon_engagement_status field. The re-engagement alert
// checks previousPropertyValue to confirm the contact
// was Cold or Dormant before the status improved.
// ============================================================

// ---- Properties routed to the Normalization Engine ----
const NORMALIZATION_PROPERTIES = new Set([
  'jobtitle',
  'job_function',
  'seniority',
  'industry',
  'company',
  'annualrevenue',
  'numberofemployees',
  'num_employees',
  // Company properties
  'name',
  'type',
  'hs_annual_revenue'
]);

// ---- Properties routed to the Re-engagement Alert ----
const REENGAGEMENT_PROPERTIES = new Set([
  'canon_engagement_status'
]);

// ---- Parse payload ----
const body   = $input.first().json;
const events = Array.isArray(body) ? body : [body];

if (events.length === 0) {
  console.log('[ROUTER] Empty payload received.');
  return [];
}

// ---- Classify each event ----
const classified = events.map(event => {
  const propertyName = event.propertyName || '';
  const eventType    = event.eventType    || '';
  const objectType   = eventType.includes('contact') ? 'contact' :
                       eventType.includes('company') ? 'company' : 'unknown';

  let destination = 'DROP';
  if (NORMALIZATION_PROPERTIES.has(propertyName)) destination = 'NORMALIZATION';
  else if (REENGAGEMENT_PROPERTIES.has(propertyName)) destination = 'REENGAGEMENT';

  console.log(`[ROUTER] ${propertyName} (${objectType}) → ${destination}`);
  return { destination, objectType, propertyName, originalEvent: event };
});

// ---- Group by destination ----
const grouped = classified.reduce((acc, item) => {
  if (!acc[item.destination]) acc[item.destination] = [];
  acc[item.destination].push(item.originalEvent);
  return acc;
}, {});

console.log('[ROUTER] Summary:', JSON.stringify(
  Object.fromEntries(Object.entries(grouped).map(([k, v]) => [k, v.length]))
));

return [{
  json: {
    normalizationEvents: grouped['NORMALIZATION'] || [],
    reengagementEvents:  grouped['REENGAGEMENT']  || [],
    droppedEvents:       grouped['DROP']           || []
  }
}];

// ============================================================
// ROUTE EVENTS TO TARGET WORKFLOWS
// ============================================================
// ⚠️ UPDATE THESE TWO URLS before activating:
//
//   NORMALIZATION_WEBHOOK_URL
//     Copy from Webhook node in Normalization Engine workflow
//
//   REENGAGEMENT_WEBHOOK_URL
//     Copy from Webhook node in Re-engagement Alert workflow
// ============================================================

const NORMALIZATION_WEBHOOK_URL = 'PASTE_NORMALIZATION_WEBHOOK_URL_HERE';
const REENGAGEMENT_WEBHOOK_URL  = 'PASTE_REENGAGEMENT_WEBHOOK_URL_HERE';

const { normalizationEvents, reengagementEvents, droppedEvents } = $input.first().json;

const results = [];

// ---- Forward to Normalization Engine ----
if (normalizationEvents.length > 0) {
  try {
    if (NORMALIZATION_WEBHOOK_URL === 'PASTE_NORMALIZATION_WEBHOOK_URL_HERE') {
      throw new Error('NORMALIZATION_WEBHOOK_URL not configured.');
    }
    const response = await fetch(NORMALIZATION_WEBHOOK_URL, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify(normalizationEvents)
    });
    console.log(`[ROUTER] → Normalization: ${normalizationEvents.length} event(s), HTTP ${response.status}`);
    results.push({ destination: 'NORMALIZATION', events: normalizationEvents.length, status: response.status });
  } catch (err) {
    console.error(`[ROUTER] ✗ Normalization forward failed: ${err.message}`);
    results.push({ destination: 'NORMALIZATION', error: err.message });
  }
}

// ---- Forward to Re-engagement Alert ----
if (reengagementEvents.length > 0) {
  try {
    if (REENGAGEMENT_WEBHOOK_URL === 'PASTE_REENGAGEMENT_WEBHOOK_URL_HERE') {
      throw new Error('REENGAGEMENT_WEBHOOK_URL not configured.');
    }
    const response = await fetch(REENGAGEMENT_WEBHOOK_URL, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify(reengagementEvents)
    });
    console.log(`[ROUTER] → Re-engagement: ${reengagementEvents.length} event(s), HTTP ${response.status}`);
    results.push({ destination: 'REENGAGEMENT', events: reengagementEvents.length, status: response.status });
  } catch (err) {
    console.error(`[ROUTER] ✗ Re-engagement forward failed: ${err.message}`);
    results.push({ destination: 'REENGAGEMENT', error: err.message });
  }
}

// ---- Log dropped events ----
if (droppedEvents.length > 0) {
  const props = droppedEvents.map(e => e.propertyName || 'unknown').join(', ');
  console.log(`[ROUTER] Dropped ${droppedEvents.length} unrouted event(s): ${props}`);
  results.push({ destination: 'DROP', events: droppedEvents.length });
}

return [{ json: { routed: results, timestamp: new Date().toISOString() } }];

const error = $input.first().json;
console.error('[ROUTER ERROR]', JSON.stringify({
  workflow:  'HubSpot Webhook Router v1.1',
  error:     error.message || 'Unknown error',
  node:      error.node?.name || 'Unknown',
  timestamp: new Date().toISOString()
}));
return [{ json: { logged: true } }];
